---@class GuideQTEMgr
local GuideQTEMgr = Class('GuideQTEMgr')

function GuideQTEMgr:__init()
    --
end

function GuideQTEMgr:__delete()
    --
end

function GuideQTEMgr:Awake()
    self.processor = self.controller.gameObject:GetComponentInChildren(typeof(ChapterProcessor))
    self.timelineNotificationReceiver = self.controller.gameObject:GetComponent(typeof(TimelineNotificationReceiver))
    self.__ProcessNofity = Bind(self, self.ProcessNofity)
    self.timelineNotificationReceiver:CustomOnNotify("+", self.__ProcessNofity)
    local str = self.controller.gameObject.name
    if string.startsWith(str, "QTE_OP5") or string.startsWith(str, "QTE_OP8") then
        local vec = self.controller.transform.localPosition
        vec.y = -100
        self.controller.transform.localPosition = vec
    end
    
    --KTool.SetActive(self.controller.transform:Find("Camera"), false)
    --KTool.SetActive(, false)
    self.tlCamera = self.controller.transform:Find("Camera").gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
    self.tlUICamera = self.controller.transform:Find("UICameraTop").gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
    --self:InitStack()
    self.touch = GameObject()
    self.touch.transform:SetParent(self.tlUICamera.transform:GetChild(0):Find("ChapterNewUI"))
    KTool.ResetTransform(self.touch.transform)
    self.touch.transform.localScale = Vector3(50, 50, 1)
    self.touch.name = "TouchHandler"
    self.touch.layer = 15
    self.touch:EnsureComponent(typeof(CS.UnityEngine.CanvasRenderer))
    self.touch = self.touch:EnsureComponent(typeof(CS.Engine.UI.GraphicRaycastReceiver))
    KTool.SetActive(self.touch, false)
    if not KTool.IsActiveInHierarchy(self.tlUICamera) then
        KTool.SetActive(self.tlUICamera, true)
    end
end

function GuideQTEMgr:Start()
    
end


function GuideQTEMgr:OnDestroy()
    self.timelineNotificationReceiver:CustomOnNotify("-", self.__ProcessNofity)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function GuideQTEMgr:ProcessNofity(origin, notification, context)
    local notifyType = notification:GetType()
    print("ProcessNofity", notifyType)

    if notifyType == typeof(CS.Markers.GuideLoopMarker) then
        -- guide loop marker 处理
        --self:Pause()
        --printInfo("guide %d", origin.Count)
        -- self:Resume()
        
        
        xTry(function()
            --- 触发对应的引导步骤
            ---@type GuideUtils
            local GuideUtils = import('Game.UI.Guide.GuideUtils')
            GuideUtils.SetIsForcedTrigger(true)
        end)

    elseif notifyType == typeof(CS.Markers.UIActiveMarker) then
        if notification.State then
            self:InitStack()
        else
            self:ClearStack()
        end
    elseif notifyType == typeof(CS.Game.Native.QTE.QTEFullScreenTouchMarker) then
        KTool.SetActive(self.touch, true)
        self:Pause()
        
        local proxy = UIEventProxy.Create(self.touch.gameObject)
        proxy.onPointerClick = function() 
            self:Resume()
            KTool.SetActive(self.touch, false)
            --KTool.SetActive(self.tlUICamera, false)
        end
    end
end

function GuideQTEMgr:Pause()
    self._isPause = true
    self.processor:PauseDirector()
    local director = self.processor:GetCurrentDirector()
    if not isNull(director) then
        director:Evaluate()
    end
end

function GuideQTEMgr:Resume()
    self._isPause = false
    self.processor:ResumeDirector()
end

function GuideQTEMgr:ClearStack()
    local data = self.tlCamera.gameObject:GetComponent(typeof(CS.UnityEngine.Rendering.Universal.UniversalAdditionalCameraData))
    if isNull(data) then
        return
    end
    data.cameraStack:Clear()
    data.cameraStack:Add(self.tlUICamera)
end

function GuideQTEMgr:InitStack()
    if not KTool.IsActiveInHierarchy(camCtrl.uiCamera) then
        KTool.SetActive(camCtrl.uiCamera, true)
    end
    camCtrl:InitCameraStack(self.tlCamera)
end


return GuideQTEMgr